336	 * every field of it, and because the whole record participates in that
337	 * application's behavior digest, a lane that measured something different
338	 * cannot agree with its own pair.
339	 */
340	export type WitnessApplicationJourneyEvidence = Record<string, unknown>;
341	
342	/**
343	 * One observed service-worker-script event, stripped of the two fields that
344	 * cannot reproduce: the wall-clock timestamp and the run-global sequence
345	 * number, which counts every other asset the lane happens to load. What
346	 * remains — who observed it, in what phase, for which path, with what detail —
347	 * is the substance of the observation and is identical run to run.
348	 */
349	export type WitnessServiceWorkerRequestEvent = {
350		source: string;
351		phase: string;
352		urlPath: string | null;
353		detail: Record<string, boolean | number | string | null>;
354	};
355	/** The same event with the number of times it was observed, for exact accounting. */
356	export type WitnessServiceWorkerRequestTally = WitnessServiceWorkerRequestEvent & {
357		count: number;
358	};
359	
360	export type WitnessRealAppRun = {
361		app: (typeof WITNESS_REAL_APP_NAMES)[number];
362		framework: 'react' | 'angularjs' | 'next' | 'angular';
363		lane: 'baseline' | 'migrated';
364		pass: 1 | 2;
365		result: 'pass';
366		interactions: Array<{ kind: WitnessGesture; selector: string }>;
367		assertions: string[];
368		routes: string[];
369		trackedEvents: string[];
370		witnessRecord: {
371			interactions: Array<{ kind: WitnessGesture; selector: string }>;
372			navigationPaths: string[];
373			trackedEventCounts: Record<string, number>;
374			consoleErrors: number;
375			pageErrors: number;
376			/**
377			 * Requests the browser failed, excluding the ones admitted by this run's
378			 * cancelled-duplicate-fetch category, which are recorded instance by
379			 * instance in {@link WitnessRealAppRun.cancelledDuplicateFetches}. A run
380			 * that declares no such category — every application here but the ones
381			 * that measured the behavior — has nothing to exclude, so this stays the
382			 * total number of browser-failed requests it has always been.
383			 */
384			failedRequests: number;
385		};
386		cleanPage: true;
387		offlineEvidence: WitnessOfflineEvidence;
388		servedStatic: {
389			transport: 'isolated-bounded-loopback-production-static';
390			documentFallback: 'index-only';
391			missingAssets: '404';
392			traversal: 'rejected';
393			inventory: { files: number; beforeSha256: string; afterSha256: string };
394			application: { path: 'index.html'; beforeSha256: string; afterSha256: string };
395			serviceWorkers: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
396			byteIdentical: true;
397			hmrControls: false;
398			legacyMainPrecache:
399				| {
400						state: 'exact-completed';
401						responses: Array<{
402							method: 'GET';
403							pathname: string;
404							query: '?__uncache=versionless-deterministic';
405							destination: 'empty';
406							resolvedFile: string;
407							status: 200;
408							mime: string;
409							bytes: number;
410							sha256: string;
411							urlPath: string;
412							source: 'production-static-origin';
413						}>;
414				  }
415				| { state: 'not-applicable' };
416			phonecatOrdering:
417				| {
418						state: 'data-derived-full-order';
419						datasetSha256: string;
420						orderSha256: string;
421						rows: 20;
422						comparator: 'stable-lowercase-utf16-source-order-ties';
423				  }
424				| { state: 'not-applicable' };
425			phonecatImageTransition:
426				| {
427						state: 'data-derived-visible-transition';
428						detailSha256: string;
429						defaultImage: string;
430						nonDefaultImage: string;
431						hover: 'genuine-thumbnail-mouseover';
432						transition: 'genuine-ng-click';
433						heroVisibility: 'genuine-hover';
434				  }
435				| { state: 'not-applicable' };
436			nextPrerenderPayload?: WitnessNextPrerenderPayloadEvidence;
437		};
438		observerFinalization: {
439			state: 'target-closed';
440			detach: 'owned-detach-complete';
441			pageClose: 'owned-page-close-complete';
442			workerEvents: WitnessServiceWorkerTelemetry['workerEvents'];
443		};
444		semanticDigest: string;
445		successfulNonLoopback: 0;
446		consoleErrorInventory?: WitnessConsoleErrorInventory;
447		failedRequestInventory?: WitnessFailedRequestInventory;
448		cancelledDuplicateFetches?: WitnessCancelledDuplicateFetchInventory;
449		mockedNonLoopbackSeams?: WitnessMockedNonLoopbackSeamInventory;
450		renderedStyles?: WitnessRenderedStyleEvidence;
451		applicationJourney?: WitnessApplicationJourneyEvidence;
452		scrollSurface?: WitnessScrollSurface;
453		scrollAbsence?: WitnessMeasuredScrollAbsence;
454	};
455	
456	/**
457	 * Measured scroll evidence for one route that genuinely overflows the stated
458	 * viewport. The document extents are read from the live page, and the scroll
459	 * itself is a real wheel gesture the browser driver confirms moved the
460	 * viewport — the boolean is an observation, not a claim substituted for one.
461	 */
462	export type WitnessScrollSurface = {
463		state: 'measured-genuine-viewport-scroll';
464		route: string;
465		viewport: { width: number; height: number };
466		scrollHeight: number;
467		clientHeight: number;
468		wheelDeltaY: number;
469		scrolledFromTop: true;
470		scrolled: true;
471	};
472	
473	/**
474	 * The measured counterpart of {@link WitnessScrollSurface}: evidence that a
475	 * journey looked for a scroll surface and did not find one.
476	 *
477	 * An application that pins its document to the viewport and scrolls its own
478	 * inner panels instead has no scrollable document to gesture at, and inventing
479	 * one would be a false claim. So the same generic measurement that backs a
480	 * scroll claim is taken at every visited route and recorded here instead:
481	 * `scrollHeight` never exceeds `clientHeight`, which is why no scroll coverage
482	 * is claimed. Routes are recorded individually rather than summarized, so a
483	 * route that starts overflowing later cannot hide inside a total.
484	 */
485	export type WitnessMeasuredScrollAbsence = {
486		state: 'measured-no-overflowing-document';
487		viewport: { width: number; height: number };
488		routes: Array<{ route: string; scrollHeight: number; clientHeight: number }>;
489		/** How the application keeps the document from overflowing, observed rather than assumed. */
490		documentOverflow: string;
491		claimed: false;
492	};
493	
494	export type WitnessMutationProof = {
495		app: 'react-boilerplate' | 'angular-realworld';
496		failure: 'witness-semantic-assertion';
497		intendedFailure: true;
498		restoredByteIdentically: true;
499	};
500	
501	export type WitnessRealAppReceipt = {
502		schemaVersion: typeof WITNESS_REAL_APP_SCHEMA;
503		result: 'pass';
504		provenance: Record<string, unknown>;
505		canonicalReceipts: Array<{
506			app: string;
507			path: string;
508			sha256: string;
509			canonicalDigest: string;
510		}>;
511		runs: WitnessRealAppRun[];
512		mutations: WitnessMutationProof[];
513		killedByGoogleInventory: {
514			archiveSha256: string;
515			mirrorFiles: number;
516			sourceFiles: Record<'baseline' | 'migrated', number>;
517			buildFiles: Record<'baseline' | 'migrated', number>;
518			transformEdits: 3;
519		};
520		locality: { mode: 'offline'; successfulNonLoopback: 0; osWideIsolation: false };
521		nonclaims: string[];
522		integrity: { algorithm: 'sha256'; canonicalDigest: string };
523	};
524	
525	function record(value: unknown, label: string): Record<string, unknown> {
526		if (value === null || typeof value !== 'object' || Array.isArray(value))
527			throw new Error(`Witness real-app ${label} must be an object`);
528		return value as Record<string, unknown>;
529	}
530	
531	function sha256Digest(value: unknown): value is string {
532		return typeof value === 'string' && value.length === 64;
533	}
534	
535	function sortedUniqueStrings(values: unknown): values is string[] {
536		return (
537			Array.isArray(values) &&
538			values.every((value) => typeof value === 'string') &&
539			new Set(values).size === values.length &&
540			values.join('\n') === [...values].sort().join('\n')
541		);
542	}
543	
544	function validServiceWorkerTelemetry(value: unknown): value is WitnessServiceWorkerTelemetry {
545		const telemetry = value as WitnessServiceWorkerTelemetry;
546		return (
547			telemetry?.state === 'ready' &&
548			telemetry.registration?.scriptPath === '/sw.js' &&
549			telemetry.registration.scope === '/' &&
550			telemetry.registration.active === 'activated' &&
551			(telemetry.controller === 'activated' || telemetry.controller === null) &&
552			sortedUniqueStrings(telemetry.cacheNames) &&
553			telemetry.cacheNames.length === 1 &&
554			Array.isArray(telemetry.cacheEntries) &&
555			telemetry.cacheEntries.length === 1 &&
556			telemetry.cacheEntries[0]?.name === telemetry.cacheNames[0] &&
557			sortedUniqueStrings(telemetry.cacheEntries[0].paths) &&
558			telemetry.cacheEntries[0].paths.length > 0 &&
559			telemetry.cacheEntries[0].paths.every((path) => path.startsWith('/')) &&
560			Array.isArray(telemetry.workerEvents)
561		);
562	}
563	
564	export function witnessRealAppDigest(receipt: WitnessRealAppReceipt): string {
565		const copy = structuredClone(receipt);
566		copy.integrity.canonicalDigest = '';
567		return sha256(canonicalize(copy));
568	}
569	
570	export function parseWitnessRealAppReceipt(value: unknown): WitnessRealAppReceipt {
571		const receipt = record(value, 'receipt') as WitnessRealAppReceipt;
572		if (
573			receipt.schemaVersion !== WITNESS_REAL_APP_SCHEMA ||
574			receipt.result !== 'pass' ||
575			!Array.isArray(receipt.runs) ||
576			receipt.runs.length !== WITNESS_REAL_APP_RUNS ||
577			!Array.isArray(receipt.canonicalReceipts) ||
578			receipt.canonicalReceipts.length !== WITNESS_REAL_APP_NAMES.length
579		)
580			throw new Error('Witness real-app receipt cardinality differs');
581		const expected = new Set<string>();
582		for (const app of WITNESS_REAL_APP_NAMES)
583			for (const lane of ['baseline', 'migrated'])
584				for (const pass of [1, 2]) expected.add(`${app}:${lane}:${pass}`);
585		const gestures = new Set<WitnessGesture>();
586		const semanticPasses = new Map<string, string>();
587		for (const run of receipt.runs) {
588			const key = `${run.app}:${run.lane}:${run.pass}`;
589			const served = run.servedStatic;
590			const servedStaticDiffers =
591				served?.transport !== 'isolated-bounded-loopback-production-static' ||
592				served.documentFallback !== 'index-only' ||
593				served.missingAssets !== '404' ||
594				served.traversal !== 'rejected' ||
595				!Number.isInteger(served.inventory?.files) ||
596				served.inventory.files < 1 ||
597				!sha256Digest(served.inventory.beforeSha256) ||
598				served.inventory.beforeSha256 !== served.inventory.afterSha256 ||
599				served.application?.path !== 'index.html' ||
600				!sha256Digest(served.application.beforeSha256) ||
601				served.application.beforeSha256 !== served.application.afterSha256 ||
602				!Array.isArray(served.serviceWorkers) ||
603				served.serviceWorkers.some(
604					(serviceWorker) =>
605						serviceWorker.path !== 'sw.js' ||
606						!sha256Digest(serviceWorker.beforeSha256) ||
607						serviceWorker.beforeSha256 !== serviceWorker.afterSha256,
608				) ||
609				(run.app === 'react-boilerplate'
610					? served.serviceWorkers.length !== 1
611					: served.serviceWorkers.length !== 0) ||
612				served.byteIdentical !== true ||
613				served.hmrControls !== false;
614			const expectedLegacyMain = [
615				['/favicon.ico', 'favicon.ico', 'image/x-icon'],
616				[
617					'/2f1a976c9c35ffed9b7e23cf2cbf8f19.jpg',
618					'2f1a976c9c35ffed9b7e23cf2cbf8f19.jpg',
619					'image/jpeg',
620				],
621				[
622					'/runtime.bfb7866e5bd316b6a048.js',
623					'runtime.bfb7866e5bd316b6a048.js',
624					'text/javascript',
625				],
626				['/', 'index.html', 'text/html'],
627			] as const;
628			const legacyMainPrecacheDiffers =
629				run.app === 'react-boilerplate' && run.lane === 'baseline'
630					? served.legacyMainPrecache?.state !== 'exact-completed' ||
631						served.legacyMainPrecache.responses.length !== expectedLegacyMain.length ||
632						served.legacyMainPrecache.responses.some((response, index) => {
633							const expectedResponse = expectedLegacyMain[index];
634							return (
635								expectedResponse === undefined ||
636								response.method !== 'GET' ||
637								response.pathname !== expectedResponse[0] ||
638								response.query !== '?__uncache=versionless-deterministic' ||
639								response.destination !== 'empty' ||
640								response.resolvedFile !== expectedResponse[1] ||
641								response.status !== 200 ||
642								response.mime !== expectedResponse[2] ||
643								!Number.isInteger(response.bytes) ||
644								response.bytes < 1 ||
645								!sha256Digest(response.sha256) ||
646								response.urlPath !== `${response.pathname}${response.query}` ||
647								response.source !== 'production-static-origin'
648							);
649						})
650					: served.legacyMainPrecache?.state !== 'not-applicable';
651			const phonecatOrderingDiffers =
652				run.app === 'angular-phonecat'
653					? served.phonecatOrdering?.state !== 'data-derived-full-order' ||
654						!sha256Digest(served.phonecatOrdering.datasetSha256) ||
655						!sha256Digest(served.phonecatOrdering.orderSha256) ||
656						served.phonecatOrdering.rows !== 20 ||
657						served.phonecatOrdering.comparator !==
658							'stable-lowercase-utf16-source-order-ties'
659					: served.phonecatOrdering?.state !== 'not-applicable';
660			const phonecatImageTransitionDiffers =
661				run.app === 'angular-phonecat'
662					? served.phonecatImageTransition?.state !== 'data-derived-visible-transition' ||
663						!sha256Digest(served.phonecatImageTransition.detailSha256) ||
664						!served.phonecatImageTransition.defaultImage.startsWith('img/phones/') ||
665						!served.phonecatImageTransition.nonDefaultImage.startsWith('img/phones/') ||
666						served.phonecatImageTransition.defaultImage ===
667							served.phonecatImageTransition.nonDefaultImage ||
668						served.phonecatImageTransition.hover !== 'genuine-thumbnail-mouseover' ||
669						served.phonecatImageTransition.transition !== 'genuine-ng-click' ||
670						served.phonecatImageTransition.heroVisibility !== 'genuine-hover'
671					: served.phonecatImageTransition?.state !== 'not-applicable';
672			const observerFinalizationDiffers =
673				run.observerFinalization?.state !== 'target-closed' ||
674				run.observerFinalization.detach !== 'owned-detach-complete' ||
675				run.observerFinalization.pageClose !== 'owned-page-close-complete' ||
676				!Array.isArray(run.observerFinalization.workerEvents);
677			const lifecycle =
678				run.offlineEvidence.state === 'react-shell-rendered-state-reset'
679					? run.offlineEvidence.lifecycle
680					: undefined;
681			const expectedCacheName =
682				run.lane === 'baseline'
683					? 'webpack-offline:versionless-deterministic'
684					: 'versionless-react-vite8-553cd1cc611a0851b1978bbc041ef2f8c7b9fbbd3fdd9bb68274f29364987cdc';
685			const lifecycleDiffers =
686				run.app === 'react-boilerplate'
687					? lifecycle?.state !== 'ready-online-reload-controlled-offline-reset' ||
688						!validServiceWorkerTelemetry(lifecycle.ready) ||
689						!validServiceWorkerTelemetry(lifecycle.controlled) ||
690						lifecycle.controlled.controller !== 'activated' ||
691						lifecycle.ready.cacheNames[0] !== expectedCacheName ||
692						canonicalize(lifecycle.ready.cacheEntries) !==
693							canonicalize(lifecycle.controlled.cacheEntries) ||
694						!sortedUniqueStrings(lifecycle.onlineStaticPaths) ||
695						!lifecycle.onlineStaticPaths.includes('/sw.js') ||
696						lifecycle.ready.cacheEntries[0]!.paths.some(
697							(path) =>
698								path !== '/__offline_webpack__data' &&
699								!lifecycle.onlineStaticPaths.includes(path),
700						) ||
701						lifecycle.offlineServerRequests !== 0
702					: lifecycle !== undefined;
703			if (
704				run.interactions.some((interaction) => interaction.kind === 'drag') &&
705				!(WITNESS_REAL_APP_DRAG_SURFACES as readonly string[]).includes(run.app)
706			)
707				throw new Error('Witness real-app drag must remain not-tested');
708			if (
709				!expected.delete(key) ||
710				run.result !== 'pass' ||
711				run.successfulNonLoopback !== 0 ||
712				!Array.isArray(run.interactions) ||
713				run.interactions.length === 0 ||
714				!Array.isArray(run.assertions) ||
715				run.assertions.length === 0 ||
716				servedStaticDiffers ||
717				legacyMainPrecacheDiffers ||
718				phonecatOrderingDiffers ||
719				phonecatImageTransitionDiffers ||
720				observerFinalizationDiffers ||
721				lifecycleDiffers ||
722				run.cleanPage !== true ||
723				(run.app === 'react-boilerplate'
724					? run.offlineEvidence?.state !== 'react-shell-rendered-state-reset' ||
725						run.offlineEvidence.shellRendered !== true ||
726						run.offlineEvidence.usernameReset !== true ||
727						run.offlineEvidence.repositoriesReset !== true ||
728						run.offlineEvidence.apiResponseCaching !== 'not-claimed' ||
729						run.offlineEvidence.reduxPersistence !== 'not-implemented' ||
730						run.offlineEvidence.priorResultPersistence !== 'not-implemented' ||
731						run.offlineEvidence.harnessFulfillment !==
732							'synthetic-github-route-online-only' ||
733						run.offlineEvidence.serviceWorkerEvidence?.source !== 'canonical-t060' ||
734						run.offlineEvidence.serviceWorkerEvidence.receiptPath !==
735							'evidence/runs/react-boilerplate-v4-composed/t060-run.json' ||
736						run.offlineEvidence.serviceWorkerEvidence.canonicalDigest !==
737							'52400147929220935a9ebe47a16c8dff50b5c28e9d51c930d000c99c2bdc8a21' ||
738						run.offlineEvidence.serviceWorkerEvidence.newProof !== false
739					: run.offlineEvidence?.state !== 'not-applicable') ||
740				run.semanticDigest !==
741					sha256(
742						canonicalize({
743							app: run.app,
744							framework: run.framework,
745							lane: run.lane,
746							interactions: run.interactions,
747							assertions: run.assertions,
748							routes: run.routes,
749							trackedEvents: run.trackedEvents,
750							witnessRecord: run.witnessRecord,
751							cleanPage: run.cleanPage,
752							offlineEvidence: run.offlineEvidence,
753							servedStatic: run.servedStatic,
754							observerFinalization: run.observerFinalization,
755							successfulNonLoopback: run.successfulNonLoopback,
756						}),
757					)
758			)
759				throw new Error(`Witness real-app run differs: ${key}`);
760			const pair = `${run.app}:${run.lane}`;
761			const prior = semanticPasses.get(pair);
762			if (prior !== undefined && prior !== run.semanticDigest)
763				throw new Error(`Witness real-app repeated pass differs: ${pair}`);
764			semanticPasses.set(pair, run.semanticDigest);
765			for (const interaction of run.interactions) {
766				gestures.add(interaction.kind);
767			}
768		}
769		if (
770			expected.size !== 0 ||
771			[...gestures].sort().join(',') !== 'click,drag,hover,press,scroll,type'
772		)
773			throw new Error('Witness real-app interaction coverage differs');
774		if (
775			receipt.mutations?.length !== 2 ||
776			receipt.mutations.some(
777				(mutation) =>
778					mutation.failure !== 'witness-semantic-assertion' ||
779					mutation.intendedFailure !== true ||
780					mutation.restoredByteIdentically !== true,
781			) ||
782			!receipt.mutations.some((mutation) => mutation.app === 'react-boilerplate') ||
783			!receipt.mutations.some((mutation) => mutation.app === 'angular-realworld') ||
784			receipt.killedByGoogleInventory?.transformEdits !== 3 ||
785			receipt.locality?.mode !== 'offline' ||
786			receipt.locality?.successfulNonLoopback !== 0 ||
787			receipt.locality?.osWideIsolation !== false ||
788			!receipt.nonclaims?.some((claim) => claim.includes('Drag is tested only')) ||
789			receipt.integrity?.algorithm !== 'sha256' ||
790			receipt.integrity.canonicalDigest !== witnessRealAppDigest(receipt)
791		)
792			throw new Error('Witness real-app receipt integrity or nonclaims differ');
793		return receipt;
794	}
