import { FC, useEffect, useState } from 'react';

import { FilterType } from './Filter';
import { ProductWithSlug } from '../types/Product';
import {
    Controls,
    Filter,
    List,
    Loader,
    Search,
} from '../components';

const App: FC<{ items: ProductWithSlug[] }> = ({ items }) => {
    const [listItems, updateListItems] = useState(items);
    const [searchTerm, updateSearchTerm] = useState('');
    const [activeFilter, updateActiveFilter] = useState<FilterType>('all');

    useEffect(() => {
        const regexp = new RegExp(searchTerm.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
        const list = activeFilter === 'all' ? items :
            items.filter(el => el.type === activeFilter);
        // If search goes empty
        if (searchTerm === '') {
            // Reset the list.
            updateListItems(list);
        } else {
            // Otherwise filter the list by name and description
            updateListItems(list.filter(el =>
                regexp.test(el.name.toLowerCase()) ||
                regexp.test(el.description.toLowerCase())
            ));
        }
    }, [searchTerm, activeFilter, items]);

    useEffect(() => {
        if(searchTerm !== '' && window.umami?.trackEvent)
            window.umami.trackEvent(searchTerm, 'search');
    }, [searchTerm]);

    return (
        <>
            {items.length ? <>
                <Controls>
                    <Search searchCallback={updateSearchTerm} />
                    <Filter
                        filterHandler={updateActiveFilter}
                        items={items}
                    />
                </Controls>
                <List items={listItems} />
            </> : <Loader />}
        </>
    );
}
export default App;
import Select, { Options, SingleValue } from 'react-select';

import { SRT } from '../components';
import { Product } from '../types/Product';

export type FilterType = Product['type'] | 'all';

function isFilterType(x: unknown): x is FilterType {
  switch (x) {

    case "app":
    case "hardware":
    case "service":
    case "all":
      return true;
    default:
      return false;
  }
}

type Props = {
  items: Product[];
  filterHandler: (b: FilterType) => void;
}

const Filter: React.FC<Props> = ({ items, filterHandler }) => {

  const getCount = (type: string) => items.filter(item => item.type === type).length;

  type Option = {
    value: string;
    label: string;
  }
  const selectOptions: Option[] = [
    {
      value: 'all',
      label: `All (${items.length})`,
    },
    {
      value: 'app',
      label: `Apps (${getCount('app')})`,
    },
    {
      value: 'service',
      label: `Services (${getCount('service')})`,
    },
    {
      value: 'hardware',
      label: `Hardware (${getCount('hardware')})`,
    }
  ];

  const changeHandler = (arg: SingleValue<Option>): void => {
    const filterVal = arg?.value;
    if (isFilterType(filterVal)) {
      filterHandler(filterVal);
    }
    if (window.umami?.trackEvent)
      window.umami.trackEvent(filterVal, 'filter');
  }

  return (
    <label id="listFilter">
      <SRT>Filter Graveyard List</SRT>
      <Select defaultValue={selectOptions[0]} options={selectOptions} onChange={changeHandler} instanceId="filter-select" />
    </label>
  );
}
export default Filter;
import Link from "virtual:versionless-next-static-link";
import styled from '@emotion/styled';
import { css } from '@emotion/react';

const HeaderContainer = styled.header(() => css({
    display: 'flex',
    justifyContent: 'center',
    padding: '3rem',
}));

const BrandingContainer = styled.div(() => css({
    alignItems: 'center',
    display: 'flex',
}));

const Logo = styled.div(() => css({
    display: 'block',
    marginRight: '1rem',
    width: '60px',
}));

const Title = styled.h1(() => css({
    fontSize: '2.75rem',
    fontWeight: 'lighter',
    margin: 0,
}));

const Header = () => (
    <HeaderContainer>
        <Link href="/" passHref>
            <a rel="noreferrer noopener" css={{
                borderBottom: 0,
            }}>
                <BrandingContainer>
                        <Logo>
                            <img width="60px" src="/tombstone.svg" height="60px" alt="Tombstone" />
                        </Logo>
                        <Title>Killed by Google</Title>
                </BrandingContainer>
            </a>
        </Link>
    </HeaderContainer>
);

export default Header;import _ from "lodash";
import React, { useEffect, useState } from "react";
import { FallbackAd } from './List';

interface CarbonProps {
    name: string
    serve: string
    script?: string
    placement: string
    fallback: React.ReactNode
}

export default function Carbon(props: CarbonProps) {
    const [forceUpdate, updateForceUpdate] = useState(0);
    const [showFallback, updateShowFallback] = useState(false);
    let name = props.name || "pixelmobco";
    let serve = props.serve || "CK7I42Q7";
    let placement = props.placement || "";
    let fallback = props.fallback || null;


    useEffect(() => {
        const adShowing = () => document.getElementById(`${name} #carbonads`) !== null;
        let script = document.createElement("script");
        script.defer = !!script;
        script.async = true;
        script.id = "_carbonads_js";
        script.type = "text/javascript";
        script.src = `//cdn.carbonads.com/carbon.js?serve=${serve}&placement=${placement}`;
        script.onerror = () => {
            updateShowFallback(true);
        };
        script.addEventListener("load", () => {
            if (adShowing()) {
                _.invoke((window as any)._carbonads, "refresh")
                updateForceUpdate(1);
            }
        });

        document.querySelector(`#${name}`)?.appendChild(script);
    }, [name, placement, serve])

    if (showFallback) {
        return <FallbackAd />;
    }
    return <div id={name} />;
}
