        <h2>
          <a href={props.link} target="_blank" rel="noopener noreferrer">
            {props.name}
          </a>
        </h2>
        <Description>
          {TimePhrase(props.slug)}
          {props.description}
          {getYears()}
        </Description>
      </ContentContainer>
    </ListItem>
  );
}
