import { chromium } from 'playwright';
import { join, resolve } from 'pathe';
import { startStaticServer } from '../../../../../Users/jacksm5pro/dev/open-source/versionless/packages/cli/src/witness/real-app-run.ts';

const root = '/Users/jacksm5pro/dev/open-source/versionless';
const lanes = {
	baseline: join(root, '.versionless/cache/next-killedbygoogle-v3-0-0-baseline/app/out-run1'),
	migrated: join(root, '.versionless/work/next-killedbygoogle-v3-0-0/target/dist-vite-run1'),
} as const;
const chromiumExecutable = join(
	root,
	'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
);

const probes = [
	{ label: 'document-body', selector: 'body', properties: ['background-color', 'color', 'font-family', 'margin'] },
	{ label: 'header-title', selector: 'header h1', properties: ['font-size', 'font-weight', 'margin', 'color'] },
	{ label: 'list-container', selector: 'ul', properties: ['display', 'grid-template-columns', 'gap', 'list-style-type', 'padding'] },
	{ label: 'ad-list-item', selector: 'ul > li:nth-of-type(1)', properties: ['display', 'align-items', 'justify-content', 'border-bottom-width'] },
	{ label: 'first-record-list-item', selector: 'ul > li:nth-of-type(2)', properties: ['display', 'flex', 'margin', 'box-sizing'] },
	{ label: 'first-record-title', selector: 'ul > li:nth-of-type(2) h2', properties: ['font-weight', 'margin', 'font-size'] },
	{ label: 'search-box', selector: '#searchBox', properties: ['border-bottom-color', 'font-size', 'font-weight', 'background-color'] },
];

async function lane(name: 'baseline' | 'migrated') {
	const server = await startStaticServer(lanes[name], { profile: 'current-witness' });
	const browser = await chromium.launch({ executablePath: chromiumExecutable, headless: true });
	const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
	const consoleErrors: string[] = [];
	const failed: string[] = [];
	const outcomes: string[] = [];
	await context.route('**/*', async (route) => {
		const url = route.request().url();
		if (url.startsWith(server.origin)) {
			await route.continue();
			return;
		}
		outcomes.push(`MOCK ${route.request().method()} ${url}`);
		await route.fulfill({ status: 204, contentType: 'text/plain', body: '' });
	});
	const page = await context.newPage();
	page.on('console', (message) => {
		if (message.type() === 'error') consoleErrors.push(message.text());
	});
	page.on('pageerror', (error) => consoleErrors.push(`pageerror: ${error.message}`));
	page.on('requestfailed', (request) =>
		failed.push(`${request.method()} ${request.url()} ${request.failure()?.errorText ?? ''}`),
	);
	await page.goto(server.origin, { waitUntil: 'networkidle' });
	const count = async (selector: string) => await page.locator(selector).count();
	const report: Record<string, unknown> = { lane: name };
	report.initial = {
		listItems: await count('ul > li'),
		records: await count('ul > li h2'),
		title: await page.locator('header h1').textContent(),
		filterControl: await count('#react-select-filter-select-input'),
		filterText: await page.locator('#listFilter').textContent(),
		adSlot: await page.locator('ul > li:nth-of-type(1)').innerHTML(),
		firstRecord: await page.locator('ul > li:nth-of-type(2)').innerText(),
	};
	report.scroll = await page.evaluate(() => ({
		scrollHeight: document.documentElement.scrollHeight,
		clientHeight: document.documentElement.clientHeight,
		scrollY: window.scrollY,
	}));
	report.styles = await page.evaluate((requested) => {
		return requested.map((probe) => {
			const element = document.querySelector(probe.selector)!;
			const style = getComputedStyle(element);
			const box = element.getBoundingClientRect();
			return {
				label: probe.label,
				width: box.width,
				height: box.height,
				properties: Object.fromEntries(
					probe.properties.map((property) => [property, style.getPropertyValue(property)]),
				),
			};
		});
	}, probes);
	// search
	await page.fill('#searchBox', 'Google+');
	await page.waitForTimeout(900);
	report.search = { listItems: await count('ul > li'), records: await count('ul > li h2') };
	await page.fill('#searchBox', '');
	await page.waitForTimeout(900);
	report.cleared = { listItems: await count('ul > li'), records: await count('ul > li h2') };
	// filter by keyboard
	await page.click('#react-select-filter-select-input');
	await page.keyboard.type('Apps');
	await page.keyboard.press('Enter');
	await page.waitForTimeout(400);
	report.filterKeyboard = {
		listItems: await count('ul > li'),
		records: await count('ul > li h2'),
		label: await page.locator('#listFilter').textContent(),
	};
	// filter by click
	await page.click('#react-select-filter-select-input');
	await page.waitForTimeout(200);
	report.options = await page.locator('[id^="react-select-filter-select-option"]').allTextContents();
	report.optionIds = await page
		.locator('[id^="react-select-filter-select-option"]')
		.evaluateAll((nodes) => nodes.map((node) => node.id));
	await page.click('#react-select-filter-select-option-3');
	await page.waitForTimeout(400);
	report.filterClick = {
		listItems: await count('ul > li'),
		records: await count('ul > li h2'),
		label: await page.locator('#listFilter').textContent(),
	};
	// compound
	await page.fill('#searchBox', 'Nexus');
	await page.waitForTimeout(900);
	report.compound = { listItems: await count('ul > li'), records: await count('ul > li h2') };
	await page.fill('#searchBox', '');
	await page.click('#react-select-filter-select-input');
	await page.keyboard.type('All');
	await page.keyboard.press('Enter');
	await page.waitForTimeout(900);
	report.restored = { listItems: await count('ul > li'), records: await count('ul > li h2') };
	report.groups = await page.evaluate(() => {
		const groups = [...document.querySelectorAll('ul > li:has(h2)')];
		return {
			count: groups.length,
			first: groups[0]?.querySelector('h2')?.textContent,
			firstItem: groups[0]?.querySelector('p')?.textContent,
			last: groups.at(-1)?.querySelector('h2')?.textContent,
		};
	});
	await page.reload({ waitUntil: 'networkidle' });
	await page.waitForTimeout(500);
	report.afterReload = {
		listItems: await count('ul > li'),
		records: await count('ul > li h2'),
		searchValue: await page.locator('#searchBox').inputValue(),
		label: await page.locator('#listFilter').textContent(),
	};
	report.consoleErrors = consoleErrors;
	report.failed = failed;
	report.nonLoopback = [...new Set(outcomes)];
	await context.close();
	await browser.close();
	await server.close();
	process.stdout.write(`${JSON.stringify(report, null, 1)}\n`);
}

await lane(process.argv[2] === 'migrated' ? 'migrated' : 'baseline');

