		canonical.revision !== NEXT_KILLEDBYGOOGLE_V3_SOURCE.revision ||
		canonical.eraLane.digest !== NEXT_KILLEDBYGOOGLE_V3_CANONICAL_RECEIPT.eraLaneDigest ||
